with eligible as (select s.* from sessions s where not exists (select 1 from web_events ch where ch.session_id = s.id and ch.event_time >= s.started_at)) select date_trunc('quarter', started_at) as quarter_start, sort_array(collect_set(device)) as device_list, count(*) filter (where country = 'TH') as th_rows, count(*) as row_count, grouping(date_trunc('quarter', started_at)) as grouping_level from eligible group by cube (date_trunc('quarter', started_at)) having count(*) > 1
